522			assign	alu_ce = (adf_ce_unconditional)&&(op_valid_alu);
523	
524			// verilator coverage_off
525			// Verilator lint_off unused
526			wire	unused_alu_stall = &{ 1'b0, alu_stall };
527			// Verilator lint_on  unused
528			// verilator coverage_on
529			// }}}
530		end else begin : NO_ALU_STALLS
531			// alu_stall, alu_ce
532			// {{{
533			assign	alu_stall = (master_stall);
534			//assign	alu_ce = (master_ce)&&(op_valid_alu)
535			//			&&(!clear_pipeline)
536			//			&&(!alu_stall);
537			assign	alu_ce = (adf_ce_unconditional)&&(op_valid_alu);
538	
539			// verilator coverage_off
540			// Verilator lint_off unused
541			wire	unused_alu_stall = &{ 1'b0, alu_stall };
542			// Verilator lint_on  unused
543			// verilator coverage_on
544			// }}}
545		end endgenerate
546		//
547	
548		// mem_ce
549		// {{{
550		// Note: if you change the conditions for mem_ce, you must also change
551		// alu_pc_valid.
552		//
553		assign	mem_ce = (master_ce)&&(op_valid_mem)&&(!mem_stalled)
554				&&(!clear_pipeline);
