561			// {{{
562			assign	mem_stalled = (master_stall)||((op_valid_mem)&&(
563					(i_mem_pipe_stalled)
564					||(i_bus_err)||(div_error)
565					||(!op_pipe && i_mem_busy)
566					// Stall waiting for flags to be valid
567					// Or waiting for a write to the PC register
568					// Or CC register, since that can change the
569					//  PC as well
570					||((wr_reg_ce)
571						&&((wr_write_pc)||(wr_write_cc)))));
572			// }}}
573		end else if (OPT_PIPELINED)
574		begin : GEN_MEM_STALL
575			// {{{
576			assign	mem_stalled = (master_stall)||((op_valid_mem)&&(
577					(i_bus_err)||(div_error)||(i_mem_busy)
578					// Stall waiting for flags to be valid
579					// Or waiting for a write to the PC register
580					// Or CC register, since that can change the
581					//  PC as well
582					||((wr_reg_ce)
583						&&((wr_write_pc)||(wr_write_cc)))));
584			// }}}
585		end else begin : NO_MEM_STALL
586			// {{{
587			assign	mem_stalled = master_stall || i_mem_busy;
588			// }}}
589		end endgenerate
590		// }}}
591		// }}}
592	
593		//
594		// Master stall condition
595		// {{{
596		assign	master_stall = (!master_ce)||(!op_valid)||(ill_err_i)
597				||(step && stepped)
598				||(ibus_err_flag)||(idiv_err_flag)
599				||(pending_interrupt && !o_bus_lock)&&(!alu_phase)
600				||(alu_busy)||(div_busy)||(fpu_busy)||(op_break)
601				||((OPT_PIPELINED)&&(
602					prelock_stall
603					||((i_mem_busy)&&(op_illegal))
604					||((i_mem_busy)&&(op_valid_div))
605					||(alu_illegal)||(o_break)));
606		// }}}
