610	
611		// ALU, DIV, or FPU CE ... equivalent to the OR of all three of these
612		always @(*)
613		if (OPT_PIPELINED)
614			adf_ce_unconditional =
615				(!master_stall)&&(!op_valid_mem)&&(!i_mem_rdbusy)
616				&&(!i_mem_busy || !op_wR
617					|| op_R[4:0] != { gie, CPU_CC_REG });
618		else
619			adf_ce_unconditional = (!master_stall)&&(op_valid)&&(!op_valid_mem);
620		// }}}
621		// }}}
