// wr_index
// {{{
initial	wr_index = 0;
always @(posedge i_clk)
begin
	if ((OPT_PIPELINED && (mem_ce || adf_ce_unconditional))
		||(!OPT_PIPELINED && op_valid))
	begin
		wr_index <= 0;
		/*
		if (op_valid_mem)
			wr_index <= 3'b001;
		if (op_valid_alu)
			wr_index <= 3'b010;
		if (op_valid_div)
			wr_index <= 3'b011;
		if (op_valid_fpu)
			wr_index <= 3'b100;
		*/

		wr_index[0] <= (op_valid_mem | op_valid_div);
		wr_index[1] <= (op_valid_alu | op_valid_div);
		wr_index[2] <= (op_valid_fpu);
	end

	if (OPT_DBGPORT && i_dbg_we && !o_dbg_stall)
		wr_index <= 3'b000;

	if (!IMPLEMENT_FPU)
		wr_index[2] <= 1'b0;
end
// }}}

//
// DEBUG Register write access starts here
//
// {{{
initial	dbgv = 1'b0;
always @(posedge i_clk)
if (i_reset || !r_halted)
	dbgv <= 0;
else
	dbgv <= OPT_DBGPORT && i_dbg_we && !o_dbg_stall;

always @(posedge i_clk)
if (!OPT_LOWPOWER || (OPT_DBGPORT && i_dbg_we))
	dbg_val <= i_dbg_data;

// dbg_clear_pipe
// {{{
always @(posedge i_clk)
if (i_reset || clear_pipeline || !r_halted)
	dbg_clear_pipe <= 0;
else if (OPT_DBGPORT && i_dbg_we && !o_dbg_stall)
begin
	dbg_clear_pipe <= 1'b0;

	if (!OPT_PIPELINED)
		dbg_clear_pipe <= 1'b1;
	if ((i_dbg_wreg == op_Bid)&&(op_rB))

	assign	OPT_CIS_dcdRpc = dcd_Rpc;
	// verilator lint_on  UNUSED
end endgenerate
// }}}

// op_Av -- the combinatorial A value input to the ALU/MEM/DIV stage
// {{{
// This is tricky.  First, the PC and Flags registers aren't kept in
// register set but in special registers of their own.  So step one
// is to select the right register.  Step to is to replace that
// register with the results of an ALU or memory operation, if such
// results are now available.  Otherwise, we'd need to insert a wait
// state of some type.
//
// The alternative approach would be to define some sort of
// op_stall wire, which would stall any upstream stage.
// We'll create a flag here to start our coordination.  Once we
// define this flag to something other than just plain zero, then
// the stalls will already be in place.
generate if (OPT_PIPELINED)
begin : FWD_OP_AV

	assign	op_Av = ((wr_reg_ce)&&(wr_reg_id == op_Aid))
		?  wr_gpreg_vl : r_op_Av;

end else begin : COPY_OP_AV

	assign	op_Av = r_op_Av;

end endgenerate
// }}}

// dcd_A_stall
// {{{
// Stall if we have decoded an instruction that will read register A
//	AND ... something that may write a register is running
//	AND (series of conditions here ...)
//		The operation might set flags, and we wish to read the
//			CC register
//		OR ... (No other conditions)
generate if (OPT_PIPELINED)
begin : GEN_DCDA_STALL

	assign	dcd_A_stall = (dcd_rA) // &&(dcd_valid) is checked for elsewhere
			&&((op_valid)||(i_mem_rdbusy)
				||(div_busy)||(fpu_busy))
			&&(((op_wF)||(cc_invalid_for_dcd))&&(dcd_Acc))
		||((dcd_rA)&&(dcd_Acc)&&(cc_invalid_for_dcd));
end else begin : NO_DCDA_STALL

	// There are no pipeline hazards, if we aren't pipelined
